T='''"use client";
import { useRef, useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const model = __MODEL__;
export default function Demo({slug}:{slug:string}) {
 const [seen,setSeen]=useState([false,false]); const seenRef=useRef([false,false]);
 const open=(n:number,interact:()=>void)=>{if(seenRef.current[n])return;seenRef.current[n]=true;setSeen([...seenRef.current]);interact();};
 return <Lesson slug={slug} predict={{question:model.question,options:model.options,answer:model.answer}} exploreHint="Open both evidence views; compare what each drawing shows." minInteractions={2} reveal={()=><p>{model.explanation}</p>}>
 {({locked,interact})=><div><svg viewBox="0 0 340 175" className="stage-svg" role="img" aria-label={seen[0] && seen[1] ? model.explanation : `${seen[0] ? model.labels[0] : "First view hidden"}. ${seen[1] ? model.labels[1] : "Second view hidden"}.`}>
  <rect x="5" y="8" width="155" height="150" rx="12" fill="var(--bg-2)" stroke="var(--line)"/><rect x="180" y="8" width="155" height="150" rx="12" fill="var(--bg-2)" stroke="var(--line)"/>
  {seen[0] && <g transform="translate(5 10)"><g dangerouslySetInnerHTML={{__html:model.base}}/><g dangerouslySetInnerHTML={{__html:model.one}}/><text x="78" y="142" textAnchor="middle" fill="var(--fg)" fontSize="12">{model.labels[0]}</text></g>}
  {seen[1] && <g transform="translate(180 10)"><g dangerouslySetInnerHTML={{__html:model.base}}/><g dangerouslySetInnerHTML={{__html:model.two}}/><text x="78" y="142" textAnchor="middle" fill="var(--fg)" fontSize="12">{model.labels[1]}</text></g>}
  {!seen[0] && <text x="82" y="89" textAnchor="middle" fill="var(--muted)" fontSize="24">?</text>}{!seen[1] && <text x="257" y="89" textAnchor="middle" fill="var(--muted)" fontSize="24">?</text>}
 </svg><Row><Control style={{minWidth:44,minHeight:44}} disabled={locked || seen[0]} onClick={()=>open(0,interact)}>Open first view</Control><Control style={{minWidth:44,minHeight:44}} disabled={locked || seen[1]} onClick={()=>open(1,interact)}>Open second view</Control></Row><p style={{fontSize:"0.8rem",color:"var(--muted)",textAlign:"center",margin:"4px 0"}}>Conceptual drawing · not to scale</p></div>}
 </Lesson>;
}
'''
source='Unverified source leads, not checked for this particular claim: Smithsonian Ocean fish collection https://ocean.si.edu/ocean-life/fish ; NOAA Fisheries https://www.fisheries.noaa.gov/ . An independent fact-checker must identify precise claim-level sources and species qualifications.'
for c in C:
 out=root/c['slug'];out.mkdir(parents=True,exist_ok=True)
 shift=c['id']%len(c['options']);opts=c['options'][shift:]+c['options'][:shift];answer=opts.index(c['options'][c['a']]);model={'question':c['q'],'options':opts,'answer':answer,'explanation':c['why'],'labels':c['labels'],'base':c['base'],'one':c['one'],'two':c['two']}
 (out/'Demo.tsx').write_text(T.replace('__MODEL__',json.dumps(model,ensure_ascii=False,indent=2)))
 ro=c['ro'];shift=(c['id']+1)%len(ro); recallopts=ro[shift:]+ro[:shift];recall={'question':c['rq'],'options':recallopts,'answer':recallopts.index(ro[0]),'why':c['rw']}
 meta={'slug':c['slug'],'title':c['title'],'hook':c['hook'],'domain':'life','concept':c['slug'],'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Different fish can have different structures and behaviors.'],'doesNotKnow':[c['why']]},'misconception':'The first imagined explanation must apply to this fish.','objective':c['q'],'claims':[{'id':f"life.{c['slug']}.c1",'text':c['hook']+' '+c['q']+' '+c['why']+' '+', '.join(c['labels']),'support':'source','source':source,'status':'unverified'},{'id':f"life.{c['slug']}.c2",'text':'These are conceptual drawings, not to scale or recordings of observed encounters.','support':'convention','source':'Illustration convention.','status':'unverified'},{'id':f"life.{c['slug']}.c3",'text':c['rq']+' '+c['rw'],'support':'source','source':source,'status':'unverified'}],'confidence':'','recall':recall,'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
 (out/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
Path('company/reviews/zoology-fish-next/manifest.json').write_text(json.dumps([{'plan_id':c['id'],'slug':c['slug']} for c in C],indent=2)+'\n')
